<?php get_header();pt_breadcrumb();while(have_posts()):the_post();$p=wc_get_product(get_the_ID());$sample=get_post_meta(get_the_ID(),'_pt_sample',true); ?>
<section><div class="wrap detail-product"><div class="product-gallery"><?php $ids=array_filter(array_merge([$p->get_image_id()],$p->get_gallery_image_ids()));if($ids){foreach($ids as $img)echo '<a href="'.esc_url(wp_get_attachment_image_url($img,'full')).'">'.wp_get_attachment_image($img,'large').'</a>';}else echo '<div class="product-photo"><span aria-hidden="true">◇</span><p>'.($sample?'Sample product':'Product').' · image pending</p></div>'; ?></div><div><?php if($sample)echo '<span class="sample-label">SAMPLE PRODUCT · NOT A CONFIRMED OFFERING</span>'; ?><h1><?php the_title(); ?></h1><?php if($p->get_sku())echo '<p>'.($sample?'Test fixture identifier':'SKU').': '.esc_html($p->get_sku()).'</p>';the_content(); ?><div class="product-commercial"><div><strong>MOQ</strong><span><?php echo esc_html(get_post_meta(get_the_ID(),'_pt_moq',true)?:'DATA REQUIRED'); ?></span></div><div><strong>Lead time</strong><span>DATA REQUIRED</span></div><div><strong>Warranty</strong><span>DATA REQUIRED</span></div></div><button class="btn" data-add="<?php the_ID(); ?>" data-name="<?php echo esc_attr(get_the_title()); ?>">Add to Quote</button> <a class="text-link" href="<?php echo esc_url(home_url('/request-a-quote/')); ?>">Request a Quote</a> <a class="text-link" href="https://wa.me/6584726456" target="_blank" rel="noopener noreferrer">Ask about this product on WhatsApp ↗</a></div></div></section>
<?php $imported=[['_pt_specs','Specifications'],['_pt_material','Material'],['_pt_dimensions','Dimensions'],['_pt_application','Application'],['_pt_industries_served','Industries served'],['_pt_brand','Brand'],['_pt_model','Model / Part No.'],['_pt_unit','Unit'],['_pt_origin','Country of origin']];$has_imported=false;foreach($imported as $field){if(get_post_meta(get_the_ID(),$field[0],true)){$has_imported=true;break;}}if($has_imported): ?><section class="wrap product-imported-data"><h2>Product information</h2><div class="content-grid"><?php foreach($imported as $field){$value=get_post_meta(get_the_ID(),$field[0],true);if($value)echo '<article><h3>'.esc_html($field[1]).'</h3><p>'.nl2br(esc_html($value)).'</p></article>';} ?></div></section><?php endif; ?>
<section class="pale"><div class="wrap content-grid"><?php foreach(['_pt_features'=>'Key Features','_pt_options'=>'Available Options'] as $key=>$title){$value=get_post_meta(get_the_ID(),$key,true);if($value){echo '<article><h2>'.esc_html($title).'</h2><ul>';foreach(explode("\n",$value) as $line)if(trim($line))echo '<li>'.esc_html($line).'</li>';echo '</ul></article>';}}$attributes=$p->get_attributes();if($attributes){echo '<article><h2>Specifications</h2><dl class="spec-list">';foreach($attributes as $a){if(!$a->get_visible())continue;echo '<dt>'.esc_html(wc_attribute_label($a->get_name())).'</dt><dd>'.esc_html($p->get_attribute($a->get_name())).'</dd>';}echo '</dl></article>';}if(!$attributes)echo '<article><h2>Discuss the specification</h2><p>Tell us about the application, dimensions, materials, quantities and delivery needs. Verified specifications will appear here when available.</p></article>';$downloads=$p->get_downloads();if($downloads){echo '<article class="product-downloads"><h2>Downloads</h2>';foreach($downloads as $d)echo '<p><a class="text-link" href="'.esc_url($d->get_file()).'">'.esc_html($d->get_name()).'</a></p>';echo '</article>';} ?></div></section>
<?php $related=array_filter(array_map('absint',explode(',',get_post_meta(get_the_ID(),'_pt_related',true))));if($related){$q=new WP_Query(['post_type'=>'product','post__in'=>$related,'post_status'=>'publish','meta_query'=>pt_sample_query(),'posts_per_page'=>4]);if($q->posts){echo '<section><div class="wrap"><h2>Related Products</h2>';pt_cards($q->posts);echo '</div></section>';}}pt_supply_links('',get_the_ID());endwhile;pt_faq();pt_cta();get_footer(); ?>
